#include <bits/stdc++.h>
using namespace std;

struct query {
    long long x, y;
    int type;
    long long l, r;
};

struct node {
    int cnt = 0;
    long long len = 0;
};

const int maxn = 400005;

node tree[4 * maxn];
vector<long long> v;

void update(int id, int l, int r, int ql, int qr, int val) {
    if (ql <= l && r <= qr) {
        tree[id].cnt += val;
    } else {
        int mid = l + (r - l) / 2;

        if (ql <= mid) {
            update(2 * id, l, mid, ql, qr, val);
        }

        if (qr > mid) {
            update(2 * id + 1, mid + 1, r, ql, qr, val);
        }
    }

    if (tree[id].cnt > 0) {
        tree[id].len = v[r + 1] - v[l];
    } else {
        if (l == r) {
            tree[id].len = 0;
        } else {
            tree[id].len = tree[2 * id].len + tree[2 * id + 1].len;
        }
    }
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);

    int n;
    long long c;
    cin >> n >> c;

    vector<query> queries(n + 1);
    set<pair<long long, long long>> active_mountains;

    v.push_back(-1);

    for (int i = 1; i <= n; i++) {
        cin >> queries[i].x >> queries[i].y;

        long long x = queries[i].x;
        long long y = queries[i].y;

        set<pair<long long, long long>>::iterator it = active_mountains.find({x, y});

        if (it == active_mountains.end()) {
            active_mountains.insert({x, y});
            queries[i].type = 1;
        } else {
            active_mountains.erase(it);
            queries[i].type = -1;
        }

        long long l = max(0LL, x - y);
        long long r = min(c, x + y);

        queries[i].l = l;
        queries[i].r = r;

        if (l < r) {
            v.push_back(l);
            v.push_back(r);
        }
    }

    sort(v.begin() + 1, v.end());
    v.erase(unique(v.begin() + 1, v.end()), v.end());

    int m = (int)v.size() - 1;

    debug(n, c, m);

    cout << fixed << setprecision(7);

    for (int i = 1; i <= n; i++) {
        if (queries[i].l < queries[i].r && m >= 2) {
            int ql = lower_bound(v.begin() + 1, v.end(), queries[i].l) - v.begin();
            int qr = lower_bound(v.begin() + 1, v.end(), queries[i].r) - v.begin() - 1;

            if (ql <= qr) {
                update(1, 1, m - 1, ql, qr, queries[i].type);
            }
        }

        long long total_union = m >= 2 ? tree[1].len : 0;
        double ans = (double)total_union * sqrt(2.0);

        if (i <= 3 || i == n) {
            debug(i, queries[i].x, queries[i].y, queries[i].type);
            debug(queries[i].l, queries[i].r, total_union, ans);
        }

        cout << ans << '\n';
    }

    debug(tree[1].len);
}